using EEMS.Modules.Inventory.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;
namespace EEMS.Modules.Inventory;public static class InventoryModule{public static IServiceCollection AddInventoryModule(this IServiceCollection services,IConfiguration configuration){var connection=configuration.GetConnectionString("EemsDatabase");if(string.IsNullOrWhiteSpace(connection))throw new InvalidOperationException("ConnectionStrings:EemsDatabase is required.");services.AddDbContext<InventoryDbContext>(x=>x.UseNpgsql(connection));return services;}}
